// In frontend/src/DataChart.js

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS, CategoryScale, LinearScale, PointElement,
  LineElement, Title, Tooltip, Legend
} from 'chart.js';
import zoomPlugin from 'chartjs-plugin-zoom'; // Import the new plugin
import { generateColorGradient } from './colorUtils';

// Register the plugin with Chart.js
ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend, zoomPlugin);

const pidColors = [
    { main: '#00fffa', dark: '#005554' }, { main: '#0036ff', dark: '#001255' },
    { main: '#f000ff', dark: '#500055' }, { main: '#ff5300', dark: '#551c00' },
    { main: '#ffe600', dark: '#554d00' }, { main: '#a2ff00', dark: '#365500' },
];

const DataChart = ({ groupData, onTimeRangeChange }) => {
    const chartRef = useRef(null);
    const [selectedPids, setSelectedPids] = useState({
        pid1: 'Engine RPM', pid2: 'None', pid3: 'None',
    });

    const datasets = Object.entries(selectedPids)
        .filter(([, pidName]) => pidName && pidName !== 'None')
        .flatMap(([pidKey, pidName]) => {
            // --- FIX: Tie color to the dropdown's fixed position (pid1, pid2, etc.) ---
            const pidIndex = parseInt(pidKey.replace('pid', ''), 10) - 1;
            const numLogs = groupData.logs.length;
            const colorSet = pidColors[pidIndex % pidColors.length];
            const colors = generateColorGradient(colorSet.main, colorSet.dark, numLogs);

            const pidNameToSanitizedMap = groupData.logs.reduce((acc, log) => {
                const logId = log.log_id;
                groupData.combined_pids.forEach(origName => {
                    const sanitized = origName.toLowerCase().replace(/[\s\W]/g, '_');
                    if (groupData.all_columns[logId]?.includes(sanitized)) {
                        if (!acc[origName]) acc[origName] = {};
                        acc[origName][logId] = sanitized;
                    }
                });
                return acc;
            }, {});

            return groupData.logs.map((log, logIndex) => {
                const logId = log.log_id;
                const logData = groupData.all_data[logId] || [];
                const pidSanitized = pidNameToSanitizedMap[pidName]?.[logId];

                if (logData.length === 0 || !pidSanitized) return null;
                const startTime = logData[0].timestamp;
                const data = logData.map(d => ({
                    x: (d.timestamp - startTime) / 1000,
                    y: d[pidSanitized]
                }));

                return {
                    label: `${log.file_name} - ${pidName}`, data,
                    borderColor: colors[logIndex], backgroundColor: colors[logIndex],
                    yAxisID: `y${pidIndex + 1}`, tension: 0.2, pointRadius: 0, borderWidth: 2,
                };
            }).filter(Boolean);
        });

    const handlePidChange = (pidKey, value) => {
        setSelectedPids(prev => ({ ...prev, [pidKey]: value }));
    };

    const handleZoomOrPan = (chart) => {
        const { min, max } = chart.scales.x;
        onTimeRangeChange({ min, max });
    };

    const resetZoom = useCallback(() => {
        const chart = chartRef.current;
        if (chart) {
            chart.resetZoom();
            handleZoomOrPan(chart);
        }
    }, []);

    const setInitialZoom = useCallback(() => {
        const chart = chartRef.current;
        if (chart) {
            chart.options.scales.x.min = 0;
            chart.options.scales.x.max = 600; // 10 minutes
            chart.update('none');
            handleZoomOrPan(chart);
        }
    }, []);

    useEffect(() => {
        setInitialZoom();
    }, [groupData, setInitialZoom]);

    const options = {
        responsive: true, maintainAspectRatio: false,
        interaction: { mode: 'index', intersect: false },
        scales: {
            x: { type: 'linear', title: { display: true, text: 'Elapsed Time (seconds)' } },
            y1: { type: 'linear', display: selectedPids.pid1 !== 'None', position: 'left', title: { display: true, text: selectedPids.pid1, color: pidColors[0].main }, ticks: { color: pidColors[0].main } },
            y2: { type: 'linear', display: selectedPids.pid2 !== 'None', position: 'left', grid: { drawOnChartArea: false }, title: { display: true, text: selectedPids.pid2, color: pidColors[2].main }, ticks: { color: pidColors[2].main } },
            y3: { type: 'linear', display: selectedPids.pid3 !== 'None', position: 'right', grid: { drawOnChartArea: false }, title: { display: true, text: selectedPids.pid3, color: pidColors[4].main }, ticks: { color: pidColors[4].main } },
        },
        // --- FIX: Configure the zoom plugin ---
        plugins: {
            title: { display: true, text: 'Trip Group Log Comparison' },
            zoom: {
                pan: { enabled: true, mode: 'x' },
                zoom: { wheel: { enabled: true }, pinch: { enabled: true }, mode: 'x' },
                // This function is called after a zoom or pan action
                onZoomComplete: ({ chart }) => handleZoomOrPan(chart),
                onPanComplete: ({ chart }) => handleZoomOrPan(chart),
            }
        },
    };

    const pidSelector = (pidKey, colorIndex) => (
        <select value={selectedPids[pidKey]} onChange={(e) => handlePidChange(pidKey, e.target.value)} style={{ borderColor: pidColors[colorIndex].main, color: pidColors[colorIndex].main, marginRight: '10px' }}>
            <option>None</option>
            {groupData.combined_pids.map(pid => <option key={pid} value={pid}>{pid}</option>)}
        </select>
    );

    return (
        <div>
            <div className="controls" style={{ padding: '10px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                    {pidSelector('pid1', 0)}
                    {pidSelector('pid2', 2)}
                    {pidSelector('pid3', 4)}
                </div>
                <div>
                    <button onClick={resetZoom}>Reset Zoom</button>
                </div>
            </div>
            <div style={{ height: '480px' }}>
                <Line ref={chartRef} options={options} data={{ datasets }} />
            </div>
        </div>
    );
};

export default DataChart;
